<?php
if(!preg_match('#^/pagar/([A-Za-z0-9_-]+)$#',$path,$match)){http_response_code(404);exit('Not found');}
$stmt=db()->prepare('SELECT * FROM payment_links WHERE token_hash=?');$stmt->execute([token_hash($match[1])]);$link=$stmt->fetch();
if(!$link||$link['status']!=='ACTIVE'||($link['expires_at']&&strtotime($link['expires_at'])<time())){http_response_code(404);exit('Link inválido, expirado ou cancelado.');}
$error=null;
if($method==='POST'){ $fields=['name','email','cpf_cnpj','phone','postal_code','address','address_number','province','city','state'];$data=[];foreach($fields as $f){$data[$f]=trim((string)($_POST[$f]??''));}foreach($fields as $f)if($data[$f]==='')$error='Preencha todos os campos obrigatórios.';if(!$error){try{$pdo=db();$pdo->beginTransaction();$pdo->prepare('INSERT INTO customers(name,email,cpf_cnpj,phone,postal_code,address,address_number,complement,province,city,state) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$data['name'],$data['email'],preg_replace('/\D+/','',$data['cpf_cnpj']),preg_replace('/\D+/','',$data['phone']),preg_replace('/\D+/','',$data['postal_code']),$data['address'],$data['address_number'],trim((string)($_POST['complement']??''))?:null,$data['province'],$data['city'],strtoupper($data['state'])]);$customerId=(int)$pdo->lastInsertId();$gateway=new AsaasGateway();$data['external_reference']='customer:'.$customerId;$gatewayId=$gateway->createCustomer($data);$pdo->prepare('UPDATE customers SET asaas_customer_id=?,external_reference=? WHERE id=?')->execute([$gatewayId,$data['external_reference'],$customerId]);$args=['gateway_customer_id'=>$gatewayId,'amount_cents'=>(int)$link['amount_cents'],'description'=>$link['description'],'external_reference'=>'link:'.$link['id'],'due_date'=>date('Y-m-d'),'cycle'=>'MONTHLY'];$result=$link['payment_type']==='SUBSCRIPTION'?$gateway->createSubscription($args):$gateway->createPayment($args);$pdo->commit();$pdo->prepare("UPDATE payment_links SET uses_count=uses_count+1,status=IF(max_uses IS NOT NULL AND uses_count+1>=max_uses,'USED',status),customer_id=? WHERE id=?")->execute([$customerId,$link['id']]);if(!empty($result['invoiceUrl'])){header('Location: '.$result['invoiceUrl'],true,303);exit;}$error='Cobrança criada, mas o gateway não retornou o link.';}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log($e->getMessage());$error='Não foi possível criar a cobrança. Verifique os dados e tente novamente.';}}
}
?><!doctype html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pagamento | Checkout 360BH</title><link rel="stylesheet" href="/assets/checkout.css"></head><body><main class="checkout"><div class="brand">360BH<small>Checkout seguro de pagamento</small></div><section class="card"><h1><?=htmlspecialchars($link['description'])?></h1><div class="value">R$ <?=money((int)$link['amount_cents'])?></div><?php if($error):?><div class="error"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><div class="grid"><div class="field"><label>Nome completo *</label><input name="name" value="<?=htmlspecialchars($_POST['name']??'')?>" required></div><div class="field"><label>E-mail *</label><input name="email" type="email" value="<?=htmlspecialchars($_POST['email']??'')?>" required></div><div class="field"><label>CPF/CNPJ *</label><input name="cpf_cnpj" required></div><div class="field"><label>Celular com DDD *</label><input name="phone" type="tel" required></div><div class="field"><label>CEP *</label><input name="postal_code" required></div><div class="field"><label>Logradouro *</label><input name="address" required></div><div class="field"><label>Número *</label><input name="address_number" required></div><div class="field"><label>Complemento</label><input name="complement"></div><div class="field"><label>Bairro *</label><input name="province" required></div><div class="field"><label>Cidade *</label><input name="city" required></div><div class="field"><label>Estado *</label><input name="state" maxlength="2" required></div></div><div class="actions"><button class="btn">Continuar para pagamento</button></div></form><p class="note">Seus dados serão enviados com segurança ao gateway de pagamento. Não armazenamos cartão ou código de segurança.</p></section></main></body></html><?php exit;
